-- =====================================================================
-- Waterdrop — weekly stock check (every Sunday 8:00 AM India time the
-- customer is asked how many full cans they have; their count corrects the
-- stock), customer locations for the supplier map, first-come order queue.
-- GENERATED by scripts/gen-migration-18.py (do not edit by hand).
-- =====================================================================

alter table public.notifications drop constraint notifications_notification_type_check;
alter table public.notifications add constraint notifications_notification_type_check check (notification_type in (
  'low_stock', 'critical_stock', 'order_recommended', 'new_order', 'order_accepted', 'order_status',
  'delivery_scheduled', 'delivery_confirmation_required', 'delivery_confirmed', 'delivery_shortage',
  'bill_generated', 'payment_due', 'payment_overdue', 'payment_received', 'payment_submitted',
  'correction_request', 'account', 'system', 'stock_check'
));
alter table public.customers add column last_stock_check_at timestamptz;

-- Customer (or family member) counts their full cans; the ledger is corrected to match.
create or replace function public.customer_stock_check(p_customer_id uuid, p_count integer) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  c public.customers := public.customer_for_actor(p_customer_id, false);
  v_now integer;
  v_has boolean;
  v_delta integer;
  v_owner uuid;
begin
  if p_count is null or p_count < 0 or p_count > 1000 then
    raise exception 'Enter a number of cans between 0 and 1000' using errcode = '22023';
  end if;
  select current_stock, has_opening_stock into v_now, v_has from public.customer_stock where customer_id = c.id;
  if not coalesce(v_has, false) then
    insert into public.inventory_transactions (supplier_id, customer_id, transaction_type, quantity, reference_type,
                                               transaction_date, idempotency_key, created_by, notes)
    values (c.supplier_id, c.id, 'opening_stock', p_count, 'manual', public.customer_local_date(c.id),
            'opening:' || c.id, auth.uid(), 'Stock counted by customer');
    v_delta := p_count;
  else
    v_delta := p_count - coalesce(v_now, 0);
    if v_delta <> 0 then
      insert into public.inventory_transactions (supplier_id, customer_id, transaction_type, quantity, reference_type,
                                                 transaction_date, created_by, notes)
      values (c.supplier_id, c.id, 'adjustment', v_delta, 'manual', public.customer_local_date(c.id), auth.uid(),
              format('Weekly stock check: customer counted %s (app showed %s)', p_count, coalesce(v_now, 0)));
    end if;
  end if;
  update public.customers set last_stock_check_at = now() where id = c.id;
  perform public.refresh_prediction(c.id);
  -- Big differences are worth a look by the supplier.
  if v_has and abs(v_delta) >= 3 then
    select owner_id into v_owner from public.suppliers where id = c.supplier_id;
    perform public.notify(v_owner, 'stock_check', 'info', format('%s updated their stock', c.customer_name),
      format('%s counted %s cans (app showed %s).', c.customer_name, p_count, coalesce(v_now, 0)),
      '/supplier/customers/' || c.id, jsonb_build_object('customer_id', c.id, 'delta', v_delta));
  end if;
  perform public.write_audit('stock.customer_check', 'customer', c.id, c.supplier_id,
    jsonb_build_object('counted', p_count, 'was', v_now, 'delta', v_delta));
  return jsonb_build_object('stock', p_count, 'change', v_delta);
end $$;
